import{_ as s}from"./chunks/locator-healing-capture.CwzxfSiD.js";import{_ as i}from"./chunks/locator-healing.BjNtRxlF.js";import{_ as o,C as n,o as r,c as l,j as a,a as h,E as c,ak as d}from"./chunks/framework.sV-XtlWr.js";const p="/diagrams/locator-healing-resolution.svg",x=JSON.parse(`{"title":"Locator healing","description":"When a locator breaks, ranked replacements captured from the last passing run, a recommended fix in your suite's style, and pickers for local runs.","frontmatter":{"title":"Locator healing","description":"When a locator breaks, ranked replacements captured from the last passing run, a recommended fix in your suite's style, and pickers for local runs.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/locator-healing.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/locator-healing.html"}],["meta",{"property":"og:title","content":"Locator healing | Piwi Dashboard"}],["meta",{"property":"og:description","content":"When a locator breaks, ranked replacements captured from the last passing run, a recommended fix in your suite's style, and pickers for local runs."}]]},"headers":[],"relativePath":"features/locator-healing.md","filePath":"features/locator-healing.md","lastUpdated":1790960291000}`),g={name:"features/locator-healing.md"};function u(m,e,k,f,y,b){const t=n("Needs");return r(),l("div",null,[e[0]||(e[0]=a("h1",{id:"locator-healing",tabindex:"-1"},[h("Locator healing "),a("a",{class:"header-anchor",href:"#locator-healing","aria-label":'Permalink to "Locator healing"'},"​")],-1)),c(t,{reporter:"",fixtures:""}),e[1]||(e[1]=d('<p>When a locator stops matching (a button was renamed, an element moved, a hashed class changed), Piwi suggests concrete, ranked replacements, captured from the last run where the test passed, instead of leaving you to guess. Healing is read-only: it never rewrites your test. <a href="./auto-heal.html">Auto-heal PRs</a> is the separate, opt-in feature that opens the fix as a pull request.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>While tests run, the <a href="/guide/capture-fixtures.html">capture fixtures</a> record a <a href="/guide/concepts.html#locator-snapshot">locator snapshot</a> after each successful action <strong>or passing web-first assertion</strong> (a passing <code>expect(locator).toBeVisible()</code> proves the element resolved just as a click does): the target element&#39;s attributes, plus alternative locators ranked by a stability score (<code>data-testid</code> = 100, role + accessible name ≈ 90, semantic CSS ≈ 35–40, hash-suffixed ≈ 10). Capture also generates <strong>rename-proof</strong> alternatives: locators scoped to a stable ancestor (<code>getByTestId(&#39;signup-form&#39;).getByRole(&#39;textbox&#39;)</code> ≈ 72, a unique landmark ≈ 55) and a name-free <code>getByRole</code> when the element is the only one of its role. Each candidate is checked against the live page: an ambiguous test id, id, <code>name</code> or class is dropped, and an ambiguous role, text, placeholder, alt or title candidate ranks below every unique one. Input values are never captured.</p><figure><img src="'+s+'" alt="Diagram of the capture flow: a successful action or passing assertion goes through the capture proxy to an in-page element probe, which produces ranked alternative locators stored as one row per call site"><figcaption>Capture runs while tests pass: every locator that proves it resolves leaves behind ranked, uniqueness-checked replacements for the day it breaks.</figcaption></figure><p>When a locator later fails, the server looks for replacements, most trustworthy first:</p><ol><li><strong>Diff rename</strong>: the run&#39;s own diff renamed the string the locator finds its element by, at this call site, as <a href="./preflight.html">Locator preflight</a> predicts it with a <em>likely</em> break. The replacement is the same locator with the new string, and the panel says where: &quot;“Pay now” became “Pay” in CheckoutButton.vue:14&quot;. It needs a run with a diff (a pull request, or a commit after a passing run) and a source-control token. Its edit replaces the string inside your quotes, and an <a href="./auto-heal.html">auto-heal PR</a> can use it.</li><li><strong>Prior run</strong>: the same call site (<code>file:line:col</code>, or <code>file:line</code> when only the column moved) had a passing snapshot.</li><li><strong>Fingerprint</strong>: the call site moved lines, but the locator matches a prior snapshot.</li><li><strong>Cross-test</strong>: another test in the project captured the same locator.</li><li><strong>ARIA fallback</strong>: no snapshot exists, so limited suggestions come from the failure-time ARIA snapshot.</li></ol><p>A snapshot found by rungs 2 to 4 is then checked against the failing page&#39;s ARIA snapshot. When the element is gone under its old name and a confident match exists, fresh locators for the element it most likely became replace the stored ones (an <strong>element match</strong>), matched by role, heading level and, on a total rename, its position among elements of the same role.</p><figure><img src="'+p+'" alt="Diagram of the healing resolution flow: the failing error is parsed into a locator signature and call site, matched through the stored history, checked against the failing page&#39;s ARIA snapshot, and shown in the Locator fix panel"><figcaption>Every stored match is checked against the failing page before anything is recommended.</figcaption></figure><p>A single <strong>recommended fix</strong> is highlighted. It keeps your locator <em>style</em> where that style is stable enough, and only otherwise escalates to the sturdiest alternative or advises adding a <code>data-testid</code>. When the stored accessible name is provably gone from the failing page, name-based alternatives, the failing locator included, stay listed but are never recommended.</p><p>When a strict-mode violation matched several elements and only <strong>one is visible</strong>, the panel also suggests adding Playwright&#39;s <code>.visible()</code> (1.63 and later), the right fix when the duplicates are hidden copies rather than a naming problem.</p><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><p>The <strong>Locator fix</strong> section of <strong>More ways to fix</strong>, on the <a href="./evidence.html#one-execution-diagnosis-first">execution</a> and failure cluster pages. The same result goes into the <a href="./ai-diagnosis.html#locator-healing">AI diagnosis</a> context and the <a href="./fix-plans.html">fix plan</a>, and reaches agents through the <code>get_locator_healing</code> <a href="/features/mcp.html">MCP tool</a>.</p><figure><img src="'+i+`" alt="Locator fix panel showing ranked replacement locators with stability scores and a recommended fix"><figcaption>The Locator fix panel: replacements ranked by stability score, with a recommended fix and a copy button for each.</figcaption></figure><h2 id="use-it" tabindex="-1">Use it <a class="header-anchor" href="#use-it" aria-label="Permalink to &quot;Use it&quot;">​</a></h2><p>Copy the recommended fix, or another alternative, and change the line the panel names. With an uploaded trace, <strong>Pick from trace</strong> opens the failure in the dashboard&#39;s <a href="./evidence.html#trace-viewer">trace viewer</a>, whose <em>Pick locator</em> tool works on the recorded page snapshots, so a CI failure nobody watched can still be picked visually. A replacement you confirmed with a picker shows a <strong>Your pick</strong> badge and becomes the recommended fix.</p><h2 id="inspect-the-failing-page-live-local-runs" tabindex="-1">Inspect the failing page live (local runs) <a class="header-anchor" href="#inspect-the-failing-page-live-local-runs" aria-label="Permalink to &quot;Inspect the failing page live (local runs)&quot;">​</a></h2><p>With <code>inspectOnFailure: true</code> (or <code>PIWI_INSPECT_ON_FAIL=true</code>), a failing test opens <strong>Piwi&#39;s own inspector overlay</strong> on its still-open page right before the browser closes. Click any element to get ranked, uniqueness-checked locators for it; one you confirm is recorded like a pick. It is not Playwright&#39;s inspector, so what you confirm flows back into the healing data when the failure names a locator to replace.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux / macOS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_INSPECT_ON_FAIL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headed</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows (PowerShell)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:PIWI_INSPECT_ON_FAIL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;true&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headed</span></span></code></pre></div><p>Both local options need a <strong>headed</strong> browser (<code>--headed</code> or <code>headless: false</code>), never activate under CI (<code>CI</code> set to anything but empty or <code>false</code>), skip expected failures (<code>test.fail()</code>), and with retries configured open only on the final attempt. The run waits while the overlay is open (the test timeout is lifted), so prefer <code>--workers=1</code>.</p><h2 id="pick-a-replacement-locator-on-the-failing-page-local-runs" tabindex="-1">Pick a replacement locator on the failing page (local runs) <a class="header-anchor" href="#pick-a-replacement-locator-on-the-failing-page-local-runs" aria-label="Permalink to &quot;Pick a replacement locator on the failing page (local runs)&quot;">​</a></h2><p>With <code>pickLocatorOnFailure: true</code> (or <code>PIWI_PICK_LOCATOR_ON_FAIL=true</code>), a test that failed on a locator, in an action (<code>.click()</code>, <code>.fill()</code>) or an assertion (<code>expect(locator).toBeVisible()</code>), gets the same overlay aimed at the locator that broke:</p><ol><li><strong>Pick the element.</strong> The pick snaps to the nearest actionable ancestor, and <kbd>↑</kbd>/<kbd>↓</kbd> walk the DOM tree before you click, showing the locator each step would produce.</li><li><strong>Choose stable parents (optional).</strong> The element&#39;s ancestors are listed with their strongest hook (<code>data-testid</code>, <code>#id</code>, labeled landmark, role); selecting one scopes the locator to it, with a live <strong>&quot;matches N&quot;</strong> count.</li><li><strong>Confirm</strong> one of the ranked candidates.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux / macOS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_PICK_LOCATOR_ON_FAIL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headed</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows (PowerShell)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:PIWI_PICK_LOCATOR_ON_FAIL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;true&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headed</span></span></code></pre></div><p>The pick is recorded in the run&#39;s locator snapshots, so the <strong>Locator fix</strong> panel shows it first once the run uploads, as a <code>piwi-user-pick</code> attachment and annotation in the Playwright report, and in the terminal with the call site and the replacement. The picker blocks the page&#39;s own click handlers while active, so picking can&#39;t navigate away. The same picker ships as the <a href="/features/extension.html">Piwi Picker browser extension</a>, for any live page with no test run.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Healing runs only when the locator <strong>never resolved</strong>, matched nothing, or matched several elements. When it resolved and the step failed afterwards (<code>element is not enabled</code>, a wrong count, a hidden element) or the page failed to load, the panel says <em>The locator resolved; this is not a locator problem</em> (for a page that failed to load, <em>The page failed to navigate before any locator ran</em>), because rewriting a locator that found its element would be a harmful edit.</li><li>Suggestions need a passing run captured with the fixtures in place; until then only the ARIA fallback applies.</li><li>Capture costs one DOM read per call site, at most once per call site per test. Negated assertions, absence checks (<code>toBeHidden</code>, <code>toBeDetached</code>) and multi-element checks (<code>toHaveCount</code>) are never probed. Turn it off with <code>captureLocators: false</code> or <code>PIWI_CAPTURE_LOCATORS=false</code>; it is also off whenever <code>collectPerformanceMetrics</code> is <code>false</code>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/broken-locator.html">Fix a broken locator</a>: healing, used end to end on one broken locator</li><li><a href="/guide/capture-fixtures.html">Capture fixtures</a>: the one-file setup that records the locator snapshots</li><li><a href="./auto-heal.html">Auto-heal PRs</a>: when Piwi opens the recommended locator fix as a pull request itself</li><li><a href="./locator-usage.html">Who uses a locator</a>: the tests that reach an element, before you change it</li><li><a href="/features/extension.html">Browser extension</a>: the same picker on any live page, no run needed</li></ul>`,28))])}const C=o(g,[["render",u]]);export{x as __pageData,C as default};
